op isTriggerAction() -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check if this <code>AcceptActionUsage</code> is the <code>triggerAction</code> of a <code>TransitionUsage</code>.</p>\nowningType <> null and \nowningType.oclIsKindOf(TransitionUsage) and\nowningType.oclAsType(TransitionUsage).triggerAction->includes(self)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op argument(i: EInt [1,1] unordered) -> Expression [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>i</code>-th argument <code>Expression</code> of an <code>ActionUsage</code>, defined as the <code>value</code> <code>Expression</code> of the <code>FeatureValue</code> of the <code>i</code>-th owned input <code>parameter</code> of the <code>ActionUsage</code>. Return null if the <code>ActionUsage</code> has less than <code>i</code> owned input <code>parameters</code> or the <code>i</code>-th owned input <code>parameter</code> has no <code>FeatureValue</code>.</p>
if inputParameter(i) = null then null
else
    let featureValue : Sequence(FeatureValue) = inputParameter(i).
        ownedMembership->select(oclIsKindOf(FeatureValue)) in
    if featureValue->isEmpty() then null
    else featureValue->at(1).value
    endif
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op inputParameter(i: EInt [1,1] unordered) -> Feature [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>i</code>-th owned input <code>parameter</code> of the <code>ActionUsage</code>. Return null if the <code>ActionUsage</code> has less than <code>i</code> owned input <code>parameters</code>.</p>\nif inputParameters()->size() < i then null\nelse inputParameters()->at(i)\nendif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op inputParameters() -> Feature [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the owned input <code>parameters</code> of this <code>ActionUsage</code>.</p>\ninput->select(f | f.owner = self)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isSubactionUsage() -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check if this <code>ActionUsage</code> is composite and has an <code>owningType</code> that is an <code>ActionDefinition</code> or <code>ActionUsage</code> but is <em>not</em> the <code>entryAction</code> or <code>exitAction</em></code> of a <code>StateDefinition</code> or <code>StateUsage</code>. If so, then it represents an <code><em>Action</em></code> that is a <code><em>subaction</em></code> of another <code><em>Action</em></code>.</p>
isComposite and owningType <> null and
(owningType.oclIsKindOf(ActionDefinition) or
 owningType.oclIsKindOf(ActionUsage)) and
(owningFeatureMembership.oclIsKindOf(StateSubactionMembership) implies
 owningFeatureMembership.oclAsType(StateSubactionMembership).kind = 
    StateSubactionKind::do)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op multiplicityHasBounds(
      mult: Multiplicity [1,1] unordered,
      lower: EInt [1,1] unordered,
      upper: EInt [1,1] unordered
    ) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check that the given <code>Multiplicity</code> has <code>lowerBound</code> and <code>upperBound</code> expressions that are model-level evaluable to the given <code>lower</code> and <code>upper</code> values.</p>\nmult <> null and\nif mult.oclIsKindOf(MultiplicityRange) then\n    mult.oclAsType(MultiplicityRange).hasBounds(lower, upper)\nelse\n    mult.allSuperTypes()->exists(\n        oclisKindOf(MultiplicityRange) and\n        oclAsType(MultiplicityRange).hasBounds(lower, upper)\nendif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op effectiveName() -> EString [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return an effective <code>name</code> for this <code>Element</code>. By default this is the same as its <code>declaredName</code>.</p>\ndeclaredName";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op effectiveShortName() -> EString [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return an effective <code>shortName</code> for this <code>Element</code>. By default this is the same as its <code>declaredShortName</code>.</p>\ndeclaredShortName";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op escapedName() -> EString [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return <code>name</code>, if that is not null, otherwise the <code>shortName</code>, if that is not null, otherwise null. If the returned value is non-null, it is returned as-is if it has the form of a basic name, or, otherwise, represented as a restricted name according to the lexical structure of the KerML textual notation (i.e., surrounded by single quote characters and with special characters escaped).</p>";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op libraryNamespace() -> Namespace [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>By default, return the library Namespace of the <code>owningRelationship</code> of this Element, if it has one.</p>\nif owningRelationship <> null then owningRelationship.libraryNamespace()\nelse null endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op checkCondition(target: Element [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Model-level evaluate this <code>Expression</code> with the given <code>target</code>. If the result is a <code>LiteralBoolean</code>, return its <code>value</code>. Otherwise return <code>false</code>.</p>

let results: Sequence(Element) = evaluate(target) in
    result->size() = 1 and
    results->first().oclIsKindOf(LiteralBoolean) and 
    results->first().oclAsType(LiteralBoolean).value";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op evaluate(target: Element [1,1] unordered) -> Element [0,*] nonunique
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If this <code>Expression</code> <code>isModelLevelEvaluable</code>, then evaluate it using the <code>target</code> as the context <code>Element</code> for resolving <code>Feature</code> names and testing classification. The result is a collection of <code>Elements</code>, which, for a fully evaluable <code>Expression</code>, will be a <code>LiteralExpression</code> or a <code>Feature</code> that is not an <code>Expression</code>.</p>
isModelLevelEvaluable
let resultExprs : Sequence(Expression) =
    ownedFeatureMembership->
        selectByKind(ResultExpressionMembership).
        ownedResultExpression in
if resultExpr->isEmpty() then Sequence{}
else resultExprs->first().evaluate(target)
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op modelLevelEvaluable(visited: Feature [0,*] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return whether this <code>Expression</code> is model-level evaluable. The <code>visited</code> parameter is used to track possible circular <code>Feature</code> references made from <code>FeatureReferenceExpressions</code> (see the redefinition of this operation for <code>FeatureReferenceExpression</code>). Such circular references are not allowed in model-level evaluable expressions.</p>

<p>An <code>Expression</code> that is not otherwise specialized is model-level evaluable if it has no (non-implied) <code>ownedSpecializations</code> and all its <code>ownedFeatures</code> are either <code>in</code> parameters, the <code>result</code> <code>parameter</code> or a result <code>Expression</code> owned via a <code>ResultExpressionMembership</code>. The <code>parameters</code>  must not have any <code>ownedFeatures</code> or a <code>FeatureValue</code>, and the result <code>Expression</code> must be model-level evaluable.</p>
ownedSpecialization->forAll(isImplied) and 
ownedFeature->forAll(f |
    (directionOf(f) = FeatureDirectionKind::_'in' or f = result) and
        f.ownedFeature->isEmpty() and f.valuation = null or
    f.owningFeatureMembership.oclIsKindOf(ResultExpressionMembership) and
        f.oclAsType(Expression).modelLevelEvaluable(visited)
    ";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op allRedefinedFeatures() -> Feature [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return this <code>Feature</code> and all the <code>Features</code> that are directly or indirectly <code>Redefined</code> by this <code>Feature</code>.</p>\nownedRedefinition.redefinedFeature->\n    closure(ownedRedefinition.redefinedFeature)->\n    asOrderedSet()->prepend(self)\n";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op asCartesianProduct() -> Type [0,*] nonunique
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If <code>isCartesianProduct</code> is true, then return the list of <code>Types</code> whose Cartesian product can be represented by this <code>Feature</code>. (If <code>isCartesianProduct</code> is not true, the operation will still return a valid value, it will just not represent anything useful.)</p>\nfeaturingType->select(t | t.owner <> self)->\n    union(featuringType->select(t | t.owner = self)->\n        selectByKind(Feature).asCartesianProduct())->\n    union(type)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op canAccess(feature: Feature [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>A <code>Feature</code> can access another <code>feature</code> if the other <code>feature</code> is featured within one of the direct or indirect <code>featuringTypes</code> of this <code>Feature</code>.</p>
let anythingType: Element =
    subsettingFeature.resolveGlobal('Base::Anything').memberElement in
let allFeaturingTypes : Sequence(Type) =
    featuringTypes->closure(t |
        if not t.oclIsKindOf(Feature) then Sequence{}
        else
            let featuringTypes : OrderedSet(Type) = t.oclAsType(Feature).featuringType in
            if featuringTypes->isEmpty() then Sequence{anythingType}
            else featuringTypes
            endif 
        endif) in
allFeaturingTypes->exists(t | feature.isFeaturedWithin(t))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op directionFor(type: Type [1,1] unordered) -> FeatureDirectionKind [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>directionOf</code> this <code>Feature</code> relative to the given <code>type</code>.</p>\ntype.directionOf(self)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isCartesianProduct() -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>Feature</code> can be used to represent a Cartesian product of <code>Types</code>.</p>
type->size() = 1 and
featuringType.size() = 1 and
(featuringType.first().owner = self implies
    featuringType.first().oclIsKindOf(Feature) and
    featuringType.first().oclAsType(Feature).isCartesianProduct())";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isFeaturedWithin(type: Type [0,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return if the <code>featuringTypes</code> of this <code>Feature</code> are compatible with the given <code>type</code>. If <code>type</code> is null, then check if this <code>Feature</code> is explicitly or implicitly featured by <em><code>Base::Anything</code></em>. If this <code>Feature</code> has <code>isVariable = true</code>, then also consider it to be featured within its <code>owningType</code>. If this <code>Feature</code> is a feature chain whose first <code>chainingFeature</code> has <code>isVariable = true</code>, then also consider it to be featured within the <code>owningType</code> of its first <code>chainingFeature</code>.</p>
if type = null then
    featuringType->forAll(f | f = resolveGlobal('Base::Anything').memberElement)
else
    featuringType->forAll(f | type.isCompatibleWith(f)) or
    isVariable and type.specializes(owningType) or
    chainingFeature->notEmpty() and chainingFeature->first().isVariable and
        type.specializes(chainingFeature->first().owningType)
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isOwnedCrossFeature() -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return whether this <code>Feature</code> is an owned cross <code>Feature</code> of an end <code>Feature</code>.</p>\nowningNamespace <> null and \nowningNamespace.oclIsKindOf(Feature) and \nowningNamespace.oclAsType(Feature).ownedCrossFeature() = self";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op namingFeature() -> Feature [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>By default, the naming <code>Feature</code> of a <code>Feature</code> is given by its first <code>redefinedFeature</code> of its first <code>ownedRedefinition</code>, if any.</p>
if ownedRedefinition->isEmpty() then
    null
else
    ownedRedefinition->at(1).redefinedFeature
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op ownedCrossFeature() -> Feature [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If this <code>Feature</code> is an end <code>Feature</code> of its <code>owningType</code>, then return the first <code>ownedMember</code> of the <code>Feature</code> that is a <code>Feature</code>, but <em>not</em> a <code>Multiplicity</code>, <code>MetadataFeature</code>, or <code>BindingConnector</code>, and whose <code>owningMembership</code> is <em>not</em> a <code>FeatureMembership</code> or <code>FeatureValue</code>. If this exists, it is the <code>crossFeature</code> of the end <code>Feature</code>.</p>
if not isEnd or owningType = null then null
else
    let ownedMemberFeatures: Sequence(Feature) =
        ownedMember->selectByKind(Feature)->
            reject(oclIsKindOf(Multiplicity) or
                   oclIsKindOf(MetadataFeature) or
                   oclIsKindOf(BindingConnector))->
            reject(owningMembership.oclIsKindOf(FeatureMembership) or
                   owningMembership.oclIsKindOf(FeatureValue)) in
    if ownedMemberFeatures.isEmpty() then null
    else ownedMemberFeatures->first()
    endif
endif
";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op redefines(redefinedFeature: Feature [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>Feature</code> <em>directly</em> redefines the given <code>redefinedFeature</code>.</p>\nownedRedefinition.redefinedFeature->includes(redefinedFeature)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op redefinesFromLibrary(libraryFeatureName: EString [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>Feature</code> <em>directly</em> redefines the named library <code>Feature</code>. <code>libraryFeatureName</code> must conform to the syntax of a KerML qualified name and must resolve to a <code>Feature</code> in global scope.</p>\nlet mem: Membership = resolveGlobal(libraryFeatureName) in\nmem <> null and mem.memberElement.oclIsKindOf(Feature) and\nredefines(mem.memberElement.oclAsType(Feature))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op subsetsChain(first: Feature [1,1] unordered, second: Feature [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>Feature</code> directly or indirectly specializes a <code>Feature</code> whose last two <code>chainingFeatures</code> are the given <code>Features</code> <code>first</code> and <code>second</code>.</p>
allSuperTypes()->selectAsKind(Feature)->
    exists(f | let n: Integer = f.chainingFeature->size() in
        n >= 2 and
        f.chainingFeature->at(n-1) = first and
        f.chainingFeature->at(n) = second)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op typingFeatures() -> Feature [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>Features</code> used to determine the <code>types</code> of this <code>Feature</code> (other than this <code>Feature</code> itself). If this <code>Feature</code> is <em>not</em> conjugated, then the <code>typingFeatures</code> consist of all subsetted <code>Features</code>, <em>except</em> from <code>CrossSubsetting</code>, and the last <code>chainingFeature</code> (if any). If this <code>Feature</code> <em>is</em> conjugated, then the <code>typingFeatures</code> are only its <code>originalType</code> (if the <code>originalType</code> is a <code>Feature</code>).</p>

<p><strong>Note.</strong> <code>CrossSubsetting</code> is excluded from the determination of the <code>type</code> of a <code>Feature</code> in order to avoid circularity in the construction of implied <code>CrossSubsetting</code> relationships. The <code>validateFeatureCrossFeatureType</code> requires that the <code>crossFeature</code> of a <code>Feature</code> have the same <code>type</code> as the <code>Feature</code>.</p>

if not isConjugated then
    let subsettedFeatures : OrderedSet(Feature) = 
        subsetting->reject(s | s.oclIsKindOf(CrossSubsetting)).subsettedFeatures in 
    if chainingFeature->isEmpty() or
       subsettedFeature->includes(chainingFeature->last())
    then subsettedFeatures
    else subsettedFeatures->append(chainingFeature->last())
    endif
else if conjugator.originalType.oclIsKindOf(Feature) then
    OrderedSet{conjugator.originalType.oclAsType(Feature)}
else OrderedSet{}
endif endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op sourceTargetFeature() -> Feature [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the first <code>ownedFeature</code> of the first owned input <code>parameter</code> of this <code>FeatureChainExpression</code> (if any).</p>
let inputParameters : Feature = ownedFeatures->
    select(direction = _'in') in
if inputParameters->isEmpty() or 
   inputParameters->first().ownedFeature->isEmpty()
then null
else inputParameters->first().ownedFeature->first()
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op importedMemberships(excluded: Namespace [0,*] unordered) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Returns Memberships that are to become <code>importedMemberships</code> of the <code>importOwningNamespace</code>. (The <code>excluded</code> parameter is used to handle the possibility of circular Import Relationships.)</p>\n";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op instantiatedType() -> Type [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>Type</code> to act as the <code>instantiatedType</code> for this <code>InstantiationExpression</code>. By default, this is the <code>memberElement</code> of the first <code>ownedMembership</code> that is not a <code>FeatureMembership</code>, which must be a <code>Type</code>.</p>

<p><b>Note.</b> This operation is overridden in the subclass <code>OperatorExpression</code>.</p>
let members : Sequence(Element) = ownedMembership->
    reject(oclIsKindOf(FeatureMembership)).memberElement in
if members->isEmpty() or not members->first().oclIsKindOf(Type) then null
else typeMembers->first().oclAsType(Type)
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op metaclassFeature() -> MetadataFeature [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return a <code>MetadataFeature</code> whose <code>annotatedElement</code> is the <code>referencedElement</code>, whose <code>metaclass</code> is the reflective <code>Metaclass</code> corresponding to the MOF class of the <code>referencedElement</code> and whose <code>ownedFeatures</code> are bound to the MOF properties of the <code>referencedElement</code>.</p>";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isSemantic() -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check if this <code>MetadataFeature</code> has a <code>metaclass</code> which is a kind of <code><em>SemanticMetadata</code>.<p>\nspecializesFromLibrary('Metaobjects::SemanticMetadata')";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isSyntactic() -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check if this <code>MetadataFeature</code> has a <code>metaclass</code> that is a kind of <code><em>KerML::Element</em></code> (that is, it is from the reflective abstract syntax model).</p>\nspecializesFromLibrary('KerML::Element')";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op syntaxElement() -> Element [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If this <code>MetadataFeature</code> reflectively represents a model element, then return the corresponding <code>Element</code> instance from the MOF abstract syntax representation of the model.</p>\nNo OCL\nisSyntactic()";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op hasBounds(lower: EInt [1,1] unordered, upper: EInt [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>MultiplicityRange</code> represents the range bounded by the given values <code>lower</code> and <code>upper</code>, presuming the <code>lowerBound</code> and <code>upperBound</code> <code>Expressions</code> are model-level evaluable.</p>
valueOf(upperBound) = upper and
let lowerValue: UnlimitedNatural = valueOf(lowerBound) in
(lowerValue = lower or
 lowerValue = null and 
    (lower = upper or 
     lower = 0 and upper = *))
 ";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op importedMemberships(excluded: Namespace [0,*] unordered) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Derive the imported <code>Memberships</code> of this <code>Namespace</code> as the <code>importedMembership</code> of all <code>ownedImports</code>, excluding those Imports whose <code>importOwningNamespace</code> is in the <code>excluded</code> set, and excluding <code>Memberships</code> that have distinguisibility collisions with each other or with any <code>ownedMembership</code>.</p>\n\nownedImport.importedMemberships(excluded->including(self))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op membershipsOfVisibility(
      visibility: VisibilityKind [0,1] unordered,
      excluded: Namespace [0,*] unordered
    ) -> Membership [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If <code>visibility</code> is not null, return the <code>Memberships</code> of this <code>Namespace</code> with the given <code>visibility</code>, including <code>ownedMemberships</code> with the given <code>visibility</code> and <code>Memberships</code> imported with the given <code>visibility</code>. If <code>visibility</code> is null, return all <code>ownedMemberships</code> and imported <code>Memberships</code> regardless of visibility. When computing imported <code>Memberships</code>, ignore this <code>Namespace</code> and any <code>Namespaces</code> in the given <code>excluded</code> set.</p>\nownedMembership->\n    select(mem | visibility = null or mem.visibility = visibility)->\n    union(ownedImport->\n        select(imp | visibility = null or imp.visibility = visibility).\n        importedMemberships(excluded->including(self)))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op namesOf(element: Element [1,1] unordered) -> EString [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the names of the given <code>element</code> as it is known in this <code>Namespace</code>.</p>

let elementMemberships : Sequence(Membership) = 
    memberships->select(memberElement = element) in
memberships.memberShortName->
    union(memberships.memberName)->
    asSet()";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op qualificationOf(qualifiedName: EString [1,1] unordered) -> EString [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return a string with valid KerML syntax representing the qualification part of a given <code>qualifiedName</code>, that is, a qualified name with all the segment names of the given name except the last. If the given <code>qualifiedName</code> has only one segment, then return null.</p>\nNo OCL";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op resolve(qualifiedName: EString [1,1] unordered) -> Membership [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Resolve the given qualified name to the named <code>Membership</code> (if any), starting with this <code>Namespace</code> as the local scope. The qualified name string must conform to the concrete syntax of the KerML textual notation. According to the KerML name resolution rules every qualified name will resolve to either a single <code>Membership</code>, or to none.</p>

let qualification : String = qualificationOf(qualifiedName) in
let name : String = unqualifiedNameOf(qualifiedName) in
if qualification = null then resolveLocal(name)
else if qualification = '$' then  resolveGlobal(name)
else 
    let namespaceMembership : Membership = resolve(qualification) in
    if namespaceMembership = null or 
       not namespaceMembership.memberElement.oclIsKindOf(Namespace) 
    then null
    else 
        namespaceMembership.memberElement.oclAsType(Namespace).
        resolveVisible(name) 
    endif
endif endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op resolveGlobal(qualifiedName: EString [1,1] unordered) -> Membership [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Resolve the given qualified name to the named <code>Membership</code> (if any) in the effective global <code>Namespace</code> that is the outermost naming scope. The qualified name string must conform to the concrete syntax of the KerML textual notation.</p>\n\nNo OCL";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op resolveLocal(name: EString [1,1] unordered) -> Membership [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Resolve a simple <code>name</code> starting with this <code>Namespace</code> as the local scope, and continuing with containing outer scopes as necessary. However, if this <code>Namespace</code> is a root <code>Namespace</code>, then the resolution is done directly in global scope.</p>

if owningNamespace = null then resolveGlobal(name)
else
    let memberships : Membership = membership->
        select(memberShortName = name or memberName = name) in
    if memberships->notEmpty() then memberships->first()
    else owningNamespace.resolveLocal(name)
    endif
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op resolveVisible(name: EString [1,1] unordered) -> Membership [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Resolve a simple name from the visible <code>Memberships</code> of this <code>Namespace</code>.</p>

let memberships : Sequence(Membership) =
    visibleMemberships(Set{}, false, false)->
    select(memberShortName = name or memberName = name) in
if memberships->isEmpty() then null
else memberships->first()
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op unqualifiedNameOf(qualifiedName: EString [1,1] unordered) -> EString [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the simple name that is the last segment name of the given <code>qualifiedName</code>. If this segment name has the form of a KerML unrestricted name, then \"unescape\" it by removing the surrounding single quotes and replacing all escape sequences with the specified character.</p>\nNo OCL";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op visibleMemberships(
      excluded: Namespace [0,*] unordered,
      isRecursive: EBoolean [1,1] unordered,
      includeAll: EBoolean [1,1] unordered
    ) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If <code>includeAll = true</code>, then return all the <code>Memberships</code> of this <code>Namespace</code>. Otherwise, return only the publicly visible <code>Memberships</code> of this <code>Namespace</code>, including <code>ownedMemberships</code> that have a <code>visibility</code> of <code>public</code> and <code>Memberships</code> imported with a <code>visibility</code> of <code>public</code>. If <code>isRecursive = true</code>, also recursively include all visible <code>Memberships</code> of any <code>public</code> owned <code>Namespaces</code>, or, if <code>IncludeAll = true</code>, all <code>Memberships</code> of all owned <code>Namespaces</code>. When computing imported <code>Memberships</code>, ignore this <code>Namespace</code> and any <code>Namespaces</code> in the given <code>excluded</code> set.</p>

let visibleMemberships : OrderedSet(Membership) = 
    if includeAll then membershipsOfVisibility(null, excluded)
    else membershipsOfVisibility(VisibilityKind::public, excluded)
    endif in
if not isRecursive then visibleMemberships
else visibleMemberships->union(ownedMember->
    selectAsKind(Namespace).
    select(includeAll or owningMembership.visibility = VisibilityKind::public)->
    visibleMemberships(excluded->including(self), true, includeAll))
endif
";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op includeAsMember(element: Element [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Determine whether the given <code>element</code> meets all the <code>filterConditions</code>.</p>
let metadataFeatures: Sequence(AnnotatingElement) = 
    element.ownedAnnotation.annotatingElement->
        selectByKind(MetadataFeature) in
    self.filterCondition->forAll(cond | 
        metadataFeatures->exists(elem | 
            cond.checkCondition(elem)))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op parameterDirection() -> FeatureDirectionKind [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the required value of the <code>direction</code> of the <code>ownedMemberParameter</code>. By default, this is <code>in</code>.</p>\nFeatureDirectionKind::_'in'";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isSubstateUsage(isParallel: EBoolean [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check if this <code>StateUsage</code> is composite and has an <code>owningType</code> that is a <code>StateDefinition</code> or <code>StateUsage</code> with the given value of <code>isParallel</code>, but is <em>not</em> an <code>entryAction</code>, <code>doAction</code>, or <code>exitAction</code>. If so, then it represents a <code><em>StateAction</em></code> that is a <code><em>substate</em></code> or <code><em>exclusiveState</em></code> (for <code>isParallel = false</code>) of another <code><em>StateAction</em></code>.</p>
isComposite and owningType <> null and
(owningType.oclIsKindOf(StateDefinition) and
    owningType.oclAsType(StateDefinition).isParallel = isParallel or
 owningType.oclIsKindOf(StateUsage) and
    owningType.oclAsType(StateUsage).isParallel = isParallel) and
not owningFeatureMembership.oclIsKindOf(StateSubactionMembership)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op sourceFeature() -> Feature [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>Feature</code> to be used as the <code>source</code> of the <code>succession</code> of this <code>TransitionUsage</code>, which is the first <code>member</code> of the <code>TransitionUsage</code> that is a <code>Feature</code>, that is owned by the <code>TransitionUsage</code> via a <code>Membership</code> that is <em>not</em> a <code>FeatureMembership</code>, and whose <code>featureTarget</code> is an <code>ActionUsage</code>.</p>
let features : Sequence(Feature) = ownedMembership->
    reject(oclIsKindOf(FeatureMembership)).memberElement->
    selectByKind(Feature)->
    select(featureTarget.oclIsKindOf(ActionUsage)) in
if features->isEmpty() then null
else features->first()
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op triggerPayloadParameter() -> ReferenceUsage [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>payloadParameter</code> of the <code>triggerAction</code> of this <code>TransitionUsage</code>, if it has one.</p>\nif triggerAction->isEmpty() then null\nelse triggerAction->first().payloadParameter\nendif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op allRedefinedFeaturesOf(membership: Membership [1,1] unordered) -> Feature [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If the <code>memberElement</code> of the given <code>membership</code> is a <code>Feature</code>, then return all <code>Features</code> directly or indirectly redefined by the <code>memberElement</code>.</p>\nif not membership.memberElement.oclIsType(Feature) then Set{} \nelse membership.memberElement.oclAsType(Feature).allRedefinedFeatures()\nendif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op allSupertypes() -> Type [0,*] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return this <code>Type</code> and all <code>Types</code> that are directly or transitively supertypes of this <code>Type</code> (as determined by the <code>supertypes</code> operation with <code>excludeImplied = false</code>).</p>\n\nOrderedSet{self}->closure(supertypes(false))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op directionOf(feature: Feature [1,1] unordered) -> FeatureDirectionKind [0,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If the given <code>feature</code> is a <code>feature</code> of this <code>Type</code>, then return its direction relative to this <code>Type</code>, taking conjugation into account.</p>\n\ndirectionOfExcluding(f, Set{})";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op inheritableMemberships(
      excludedNamespaces: Namespace [0,*] unordered,
      excludedTypes: Type [0,*] unordered,
      excludeImplied: EBoolean [1,1] unordered
    ) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return all the non-<code>private</code> <code>Memberships</code> of all the supertypes of this <code>Type</code>, excluding any supertypes that are this <code>Type</code> or are in the given set of <code>excludedTypes</code>. If <code>excludeImplied = true</code>, then also transitively exclude any supertypes from implied <code>Specializations</code>.</p>\nlet excludingSelf : Set(Type) = excludedType->including(self) in\nsupertypes(excludeImplied)->reject(t | excludingSelf->includes(t)).\n    nonPrivateMemberships(excludedNamespaces, excludingSelf, excludeImplied)\n";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op inheritedMemberships(
      excludedNamespaces: Namespace [0,*] unordered,
      excludedTypes: Type [0,*] unordered,
      excludeImplied: EBoolean [1,1] unordered
    ) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>Memberships</code> inheritable from supertypes of this <code>Type</code> with redefined <code>Features</code> removed. When computing inheritable <code>Memberships</code>, exclude <code>Imports</code> of <code>excludedNamespaces</code>, <code>Specializations</code> of <code>excludedTypes</code>, and, if <code>excludeImplied = true</code>, all implied <code>Specializations</code>.</p>\n\nremoveRedefinedFeatures(\n    inheritableMemberships(excludedNamespaces, excludedTypes, excludeImplied))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op isCompatibleWith(otherType: Type [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>By default, this <code>Type</code> is compatible with an <code>otherType</code> if it directly or indirectly specializes the <code>otherType</code>.</p>\nspecializes(otherType)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op multiplicities() -> Multiplicity [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the owned or inherited <code>Multiplicities</code> for this <code>Type<./code>.</p>
if multiplicity <> null then OrderedSet{multiplicity}
else 
    ownedSpecialization.general->closure(t |
        if t.multiplicity <> null then OrderedSet{}
        else ownedSpecialization.general
    )->select(multiplicity <> null).multiplicity->asOrderedSet()
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op nonPrivateMemberships(
      excludedNamespaces: Namespace [0,*] unordered,
      excludedTypes: Type [0,*] unordered,
      excludeImplied: EBoolean [1,1] unordered
    ) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return the <code>public</code>, <code>protected</code> and inherited <code>Memberships</code> of this <code>Type</code>. When computing imported <code>Memberships</code>, exclude the given set of <code>excludedNamespaces</code>. When computing inherited <code>Memberships</code>, exclude <code>Types</code> in the given set of <code>excludedTypes</code>. If <code>excludeImplied = true</code>, then also exclude any supertypes from implied <code>Specializations</code>.</p>
let publicMemberships : OrderedSet(Membership) = 
    membershipsOfVisibility(VisibilityKind::public, excludedNamespaces) in
let protectedMemberships : OrderedSet(Membership) = 
    membershipsOfVisibility(VisibilityKind::protected, excludedNamespaces) in
let inheritedMemberships : OrderedSet(Membership) =
    inheritedMemberships(excludedNamespaces, excludedTypes, excludeImplied) in
publicMemberships->
    union(protectedMemberships)->
    union(inheritedMemberships)";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op removeRedefinedFeatures(memberships: Membership [0,*]) -> Membership [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Return a subset of <code>memberships</code>, removing those <code>Memberships</code> whose <code>memberElements</code> are <code>Features</code> and for which either of the following two conditions holds:</p>

<ol>
	<li>The <code>memberElement</code> of the <code>Membership</code> is included in redefined <code>Features</code> of another <code>Membership</code> in <code>memberships</code>.</li>
	<li>One of the redefined <code>Features</code> of the <code>Membership</code> is a directly <code>redefinedFeature</code> of an <code>ownedFeature</code> of this <code>Type</code>.</li>
</ol>

<p>For this purpose, the redefined <code>Features</code> of a <code>Membership</code> whose <code>memberElement</code> is a <code>Feature</code> includes the <code>memberElement</code> and all <code>Features</code> directly or indirectly redefined by the <code>memberElement</code>.</p>
let reducedMemberships : Sequence(Membership) =
    memberships->reject(mem1 |
        memberships->excluding(mem1)->
            exists(mem2 | allRedefinedFeaturesOf(mem2)->
                includes(mem1.memberElement))) in
let redefinedFeatures : Set(Feature) = 
    ownedFeature.redefinition.redefinedFeature->asSet() in
reducedMemberships->reject(mem | allRedefinedFeaturesOf(mem)->
    exists(feature | redefinedFeatures->includes(feature)))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op specializes(supertype: Type [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>Type</code> is a direct or indirect specialization of the given <code>supertype<code>.</p>
if isConjugated then 
    ownedConjugator.originalType.specializes(supertype)
else
    allSupertypes()->includes(supertype)
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op specializesFromLibrary(libraryTypeName: EString [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Check whether this <code>Type</code> is a direct or indirect specialization of the named library <code>Type</code>. <code>libraryTypeName</code> must conform to the syntax of a KerML qualified name and must resolve to a <code>Type</code> in global scope.</p>\n\nlet mem : Membership = resolveGlobal(libraryTypeName) in\nmem <> null and mem.memberElement.oclIsKindOf(Type) and\nspecializes(mem.memberElement.oclAsType(Type))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op supertypes(excludeImplied: EBoolean [1,1] unordered) -> Type [0,*]
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If this <code>Type</code> is conjugated, then return just the <code>originalType</code> of the <code>Conjugation</code>. Otherwise, return the <code>general</code> <code>Types</code> from all <code>ownedSpecializations</code> of this type, if <code>excludeImplied = false</code>, or all non-implied <code>ownedSpecializations</code>, if <code>excludeImplied = true</code>.</p>
if isConjugated then Sequence{conjugator.originalType}
else if not excludeImplied then ownedSpecialization.general
else ownedSpecialization->reject(isImplied).general
endif
endif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op referencedFeatureTarget() -> Feature [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>If <code>ownedReferenceSubsetting</code> is not null, return the <code>featureTarget</code> of the <code>referencedFeature</code> of the <code>ownedReferenceSubsetting</code>.</p>\nif ownedReferenceSubsetting = null then null\nelse ownedReferenceSubsetting.referencedFeature.featureTarget\nendif";
      }
      annotation "http://www.omg.org/spec/SysML" { };

op includeAsExposed(element: Element [1,1] unordered) -> EBoolean [1,1] unordered
      annotation "http://www.eclipse.org/emf/2002/GenModel" {
        detail "documentation" = "<p>Determine whether the given <code>element</code> meets all the owned and inherited <code>viewConditions</code>.</p>
let metadataFeatures: Sequence(AnnotatingElement) = 
    element.ownedAnnotation.annotatingElement->
        select(oclIsKindOf(MetadataFeature)) in
self.membership->selectByKind(ElementFilterMembership).
    condition->forAll(cond | 
        metadataFeatures->exists(elem | 
            cond.checkCondition(elem)))";
      }
      annotation "http://www.omg.org/spec/SysML" { };

